const question = ($json.message && $json.message.text || '').trim();
const chatId = $json.message.chat.id;

// Схема доступна боту ТОЛЬКО в виде агрегированных витрин — см.
// sql/readonly_role_selfservice.sql. Это единственные объекты, которые
// вообще способна прочитать роль n8n_selfservice, так что даже если
// промпт-инъекция заставит LLM "забыть" про ограничения, база физически
// не отдаст ничего за пределами этого списка.
const schema = `mart_channel_economics_mv(channel text, spend_month date, spend numeric, leads int, cpl numeric, customers_acquired int, cac numeric, revenue_same_month numeric, romi numeric, cumulative_spend numeric, cumulative_revenue numeric)
mart_customer_ltv_mv(customer_id int, channel text, order_id int, order_date date, total_amount numeric, order_seq int, cumulative_revenue numeric, avg_order_value numeric)
mart_cohort_retention_mv(cohort_month date, month_number int, cohort_size int, active_customers int, retention_rate numeric)
mart_sales_summary(category text, sales_month date, total_revenue numeric, order_count int)`;

// Инструкции — на английском: эмпирически проверено (см. README), что
// qwen2.5:3b-instruct на русскоязычных инструкциях почти всегда отвечал
// NOT_POSSIBLE даже на решаемые вопросы, а на английских инструкциях с
// вопросом менеджера НА РУССКОМ внутри — генерировал корректный SQL по
// всем 3 тестовым вопросам. Сам вопрос менеджера остаётся как есть.
const prompt = `You are a PostgreSQL expert. You have ONLY these tables/views available:
${schema}

Business question (in Russian): "${question}"

Write EXACTLY ONE SQL SELECT query (CTE/WITH allowed) that answers this question, using only the listed tables. No explanation, no markdown, no semicolon. If the question cannot be answered with these tables, write exactly one word: NOT_POSSIBLE.

SQL:`;

return [{ json: { prompt, question, chatId } }];

const chatId = $('Build prompt').first().json.chatId;
const question = $('Build prompt').first().json.question;
const raw = ($json.response || '').trim();

if (/^NOT_POSSIBLE\b/i.test(raw)) {
  return [{ json: { valid: false, chatId, question, errors: ['\u0432\u043e\u043f\u0440\u043e\u0441 \u0432\u044b\u0445\u043e\u0434\u0438\u0442 \u0437\u0430 \u0440\u0430\u043c\u043a\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0432\u0438\u0442\u0440\u0438\u043d'] } }];
}

// Извлечь SQL из возможных ```sql ... ``` оград
let sql = raw;
const fence = sql.match(/```(?:sql)?\s*([\s\S]*?)```/i);
if (fence) sql = fence[1];
sql = sql.replace(/;\s*$/, '').trim();

const errors = [];

// НЕ единственная защита — настоящая гарантия ниже, в правах роли
// n8n_selfservice (SELECT только на 7 витрин, read-only transaction,
// statement_timeout=5s — см. sql/readonly_role_selfservice.sql). Это —
// быстрый дружелюбный отказ до похода в БД, а не единственный барьер.
if (sql.includes(';')) errors.push('\u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u043e \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u043e\u0432');
if (/--|\/\*/.test(sql)) errors.push('SQL-\u043a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0438 \u0437\u0430\u043f\u0440\u0435\u0449\u0435\u043d\u044b');
if (!/^\s*(SELECT|WITH)\b/i.test(sql)) errors.push('\u0437\u0430\u043f\u0440\u043e\u0441 \u0434\u043e\u043b\u0436\u0435\u043d \u043d\u0430\u0447\u0438\u043d\u0430\u0442\u044c\u0441\u044f \u0441 SELECT \u0438\u043b\u0438 WITH');
const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|COPY|CALL|DO|EXECUTE|MERGE|VACUUM|REFRESH|LOCK|SET|RESET|COMMENT|SECURITY|ATTACH|DETACH|LISTEN|NOTIFY|PREPARE|DEALLOCATE)\b/i;
const m = sql.match(forbidden);
if (m) errors.push(`\u0437\u0430\u043f\u0440\u0435\u0449\u0451\u043d\u043d\u043e\u0435 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u0441\u043b\u043e\u0432\u043e: ${m[0]}`);

let finalSql = sql;
if (errors.length === 0 && !/\bLIMIT\s+\d+\b/i.test(finalSql)) {
  finalSql = `${finalSql}\nLIMIT 100`;
}

return [{ json: { valid: errors.length === 0, errors, sql: finalSql, chatId, question } }];

const chatId = $('Validate SQL').first().json.chatId;
const rows = $input.all().map(i => i.json);

if (rows.length === 1 && rows[0].error) {
  // Форма rows[0].error не всегда {message: string} — при continueOnFail
  // Postgres-нода отдаёт объект без .message в части случаев; голая
  // интерполяция объекта в шаблонную строку даёт нечитаемое "[object
  // Object]" (найдено на реальном прогоне) — приводим к строке надёжно.
  const err = rows[0].error;
  let msg;
  if (typeof err === 'string') msg = err;
  else if (err.message) msg = err.message;
  else if (err.description) msg = err.description;
  else { try { msg = JSON.stringify(err); } catch (e) { msg = String(err); } }
  const text = `\u26a0\ufe0f \u0417\u0430\u043f\u0440\u043e\u0441 \u043a \u0431\u0430\u0437\u0435 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043b\u0441\u044f: ${msg}`;
  return [{ json: { chatId, text } }];
}

if (rows.length === 0) {
  return [{ json: { chatId, text: '\u0417\u0430\u043f\u0440\u043e\u0441 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d, \u043d\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u0443\u0441\u0442.' } }];
}

const cols = Object.keys(rows[0]);
const header = cols.join(' | ');
const lines = rows.slice(0, 20).map(r => cols.map(c => r[c]).join(' | '));
const suffix = rows.length > 20 ? `\n\u2026 \u0438 \u0435\u0449\u0451 ${rows.length - 20} \u0441\u0442\u0440\u043e\u043a` : '';
const text = `${header}\n${lines.join('\n')}${suffix}`;
return [{ json: { chatId, text } }];
